        menu.addItem(
            item("Remove Filler Words…", #selector(EditorViewController.removeFillerWords(_:))))
        menu.addItem(submenuItem(transitionMenu()))
        // Road map 5's E2, beside Transition ▸: the two "how the clip arrives"
